function isInsideHome() {
  const ptx = Math.floor(player.x / T), pty = Math.floor(player.y / T);
  return ptx >= HOME_TX1 && ptx <= HOME_TX2 && pty >= HOME_TY1 && pty <= HOME_TY2;
}

function getHomeTableBonus()    { return homeFurnitureOwned('table')   ? 2.0  : 1.0; }

