function getPriceTrend(cur, prev) {
  const arrow = cur > prev * 1.05 ? '▲' : cur < prev * 0.95 ? '▼' : '─';
  const color = cur > prev * 1.05 ? '#60e060' : cur < prev * 0.95 ? '#e06060' : '#a09060';
  return { arrow, color };
}
