function gainRep(faction, amount) {
  if (!(faction in REPUTATION)) return;
  const prev = REPUTATION[faction];
  REPUTATION[faction] = Math.min(100, REPUTATION[faction] + amount);
  const next = REPUTATION[faction];
  // Fire milestone messages when a faction crosses a tier threshold
  const _milestones = [
    { at: 34, msgs: {
      mine:     '⛏ Silas nods at you as you pass. Not a greeting exactly. More like acknowledgment.',
      badlands: '💀 Crane glances up when you walk in. Doesn\'t look away. Something shifted.',
      hoboCamp: '🏕️ The camp feels a little more comfortable. People make eye contact now.',
      ocean:    '⚓ Maren says your name first today. That\'s new.',
    }},
    { at: 67, msgs: {
      mine:     '⛏ Silas told you something today he hasn\'t told anyone. You can feel the weight of it.',
      badlands: '💀 Crane mentioned something about a back room. Said it like he expected you to already know.',
      hoboCamp: '🏕️ Dr. Lena called you by name without looking up. You\'ve been coming long enough it\'s just habit now.',
      ocean:    '⚓ Maren offered you a discount without being asked. Said you\'d earned it.',
    }},
  ];
  for (const m of _milestones) {
    if (prev < m.at && next >= m.at && m.msgs[faction]) {
      setTimeout(() => showMsg(m.msgs[faction]), 2200);
    }
  }
}

let missedContracts = 0;

let contractStreak  = 0;

let streakBonus     = false;

const _msgQueue = [];

let _msgShowing = false;

function _pumpMsgQueue() {
  if (_msgQueue.length === 0) { _msgShowing = false; return; }
  _msgShowing = true;
  const next = _msgQueue.shift();
  const el = document.getElementById('msgBanner');
  if (next.isTip) el.classList.add('tip'); else el.classList.remove('tip');
  el.textContent = next.txt; el.style.opacity = '1';
  msgTimer2 = next.dur;
}

const REPUTATION = {
  town:      50,  // starts neutral — player lives here
  hoboCamp:  0,   // unknown until visited
  badlands:  0,   // unknown until visited (Crane tracks separately)
  mine:      0,   // unlocked by exploring
  // Future zones — initialized at 0, unlocked when zones are built
  city:      0,
  ocean:     0,
  secondFarm:0,
  jungle:    0,   // Eastern Expansion — The Verdant Debt
};

let msgTimer2 = 0;

function expireContracts(day) {
  const expired = activeContracts.filter(c => c.deadline < day);
  if (expired.length === 0) return;
  for (const c of expired) {
    if (c.accepted) {
      // Accepted and failed — consequences apply
      const who = c.title.includes('Mill') ? 'The miller' :
                  c.title.includes('Fish') ? 'The buyer' :
                  c.title.includes('Camp') ? 'The contact' : 'The client';
      showMsg(`📜 ${who} moved on — contract failed: ${c.icon} ${c.title}`);
      gainRep('town', -5);
      missedContracts++;
      contractStreak = 0;
      streakBonus = false;
    }
    // Unaccepted contracts just quietly rotate off — no message, no penalty
  }
  activeContracts = activeContracts.filter(c => c.deadline >= day);
}
