  WATER_DEEP: 19,
};

let exploredJungle = new Uint8Array(1);

function getJGT(x, y) {
  if (x < 0 || x >= JG_W || y < 0 || y >= JG_H) return JG.WALL;
  return jungleMap[y * JG_W + x];
}

const JG_NPCS = [
  // Eastern Dock
