const JG_FARM_X1 = 20;

const JG_FARM_X2 = 60;

const JG_FARM_Y1 = 46;

const JG_FARM_Y2 = 64;

function getJGT(x, y) {
  if (x < 0 || x >= JG_W || y < 0 || y >= JG_H) return JG.WALL;
  return jungleMap[y * JG_W + x];
}

const JG = {
  WATER:       1,
  SAND:        2,
  DOCK:        3,
  PLANK:       4,
  GRASS:       5,
  JUNGLE_FLOOR:6,
  MUD:         7,
  DIRT:        8,
  TREE:        9,
  DENSE_TREE: 10,
  ROCK:       11,
  WALL:       12,
  FLOOR:      13,
  ROAD:       14,
  CAMPFIRE:   15,
  FARM_PLOT:  16,
  EXIT:       17,
  BUSH:       18,
  WATER_DEEP: 19,
};

const JG_W = 80;

const JG_H = 80;

const jungleMap = new Uint8Array(JG_W * JG_H);

function isJGFarmTile(tx, ty) {
  if (tx < JG_FARM_X1 || tx > JG_FARM_X2) return false;
  if (ty < JG_FARM_Y1 || ty > JG_FARM_Y2) return false;
  const t = getJGT(tx, ty);
  // Only MUD, DIRT, or already-tilled jungle plots are workable
  return t === JG.MUD || t === JG.DIRT || t === JG.FARM_PLOT;
}
