    switch (animal.type) {
      case 'jungleParrot': {
        // Bright body
        c.fillStyle = '#e03020'; c.fillRect(sx - 4, sy - 10 + bob, 9, 10); // body
        c.fillStyle = '#20b060'; c.fillRect(sx - 6, sy - 8  + bob, 4, 6);  // wing
        c.fillStyle = '#f0d020'; c.fillRect(sx - 2, sy - 13 + bob, 7, 5);  // head
