      const edgePressure = Math.min(x, DJ_W - 1 - x, y) / 8;
      const density = 0.72 - edgePressure * 0.15;
      if (h < density) setDJT(x, y, h < density * 0.4 ? JG.DENSE_TREE : JG.TREE);
