          p(hx+hw,hy,3,16,B); p(hx+hw+1,hy+1,2,15,M);    // braid at back (right)
        }
      }
    }
    // 5: Pixie cut
    else{
      if(dir==='down'||dir==='up'){
        p(hx,hy-2,hw,3,B); p(hx+1,hy-2,hw-2,2,M); p(hx+1,hy-2,6,1,L);
