    p(sx-6,by-31,13,1,B);
  } else {
    // Crown: 8w × 6h centered on sx
    p(sx-4,by-39,8,1,B);
    p(sx-4,by-39,8,6,B); p(sx-3,by-39,6,5,D); p(sx-2,by-38,4,4,M); p(sx-1,by-38,2,2,L);
    p(sx-4,by-34,8,1,B); p(sx-3,by-34,6,1,band);
    // Brim: 13w centered, sx-6 to sx+6
    p(sx-6,by-33,13,1,B);
