let _introTimers    = [];

const INTRO_BEATS = [
  { text: "The land out here doesn't care about you.",         pause: 2200 },
  { text: "No one does, really.",                              pause: 1600 },
  { text: "That's why you came.",                              pause: 2000 },
  { text: `You're ${player.name||'Elias Cole'}.`,            pause: 1400 },
  { text: "You owe the bank — week by week, it comes due.",     pause: 1800 },
  { text: "Week one: $500. Week two: $700. It climbs.",          pause: 2000 },
  { text: "You have a hoe, a watering can, and three days\nbefore the heat breaks.", pause: 2600 },
  { text: "The railroad took everything else.",                pause: 2000 },
  { text: "This patch of dust is yours now.",                  pause: 2200 },
  { text: "Make it worth something.",                          pause: 2800 },
];

let _introSkipped   = false;

function typewriterInto(el, fullText, msPerChar) {
  if (_typeInterval) clearInterval(_typeInterval);
  el.textContent = '';
  const lines = fullText.split('\n');
  let lineIdx = 0, charIdx = 0;
  let displayed = '';
  _typeInterval = setInterval(() => {
    if (_introSkipped) { clearInterval(_typeInterval); return; }
    const line = lines[lineIdx];
    if (charIdx < line.length) {
      displayed += line[charIdx++];
      el.textContent = displayed;
    } else if (lineIdx < lines.length - 1) {
      displayed += '\n';
      el.textContent = displayed;
      lineIdx++; charIdx = 0;
    } else {
      clearInterval(_typeInterval);
    }
  }, msPerChar);
}

function finishIntro() {
  const screen = document.getElementById('introScreen');
  screen.style.transition = 'opacity .7s';
  screen.style.opacity = '0';
  setTimeout(() => {
    screen.classList.remove('show');
    screen.style.opacity = '';
    screen.style.transition = '';
    document.getElementById('introText').textContent = '';
    document.getElementById('introDeco').classList.remove('vis');
    // Show controls on first new game
    showControlsIfNeeded();
  }, 700);
  showMsg(`Day 1, ${player.name||'Stranger'}. The hoe won't swing itself.`);
  dSound('dawn');
}

function skipIntro() {
  _introSkipped = true;
  _introTimers.forEach(t => clearTimeout(t));
  _introTimers = [];
  if (_typeInterval)    clearInterval(_typeInterval);
  if (_introKeyRemover) window.removeEventListener('keydown', _introKeyRemover);
  finishIntro();
}

let _introKeyRemover = null;

const player = {
  x:17*T+T/2, y:26*T+T/2,
  speed:112, sprintMult:1.75,
  hp:100, maxHp:100,
  stamina:100, maxStamina:100, staminaRegen:14, _baseMaxStamina:100,
  gold:120,
  debt:0,
  w:18, h:18,
  sprinting:false,
  facing:'down', walkFrame:0, walkTimer:0,
  tool:'till', selectedSeed:'carrot',
  actionCooldown:0,
  attackCooldown:0,
  invincibleTimer:0,
  attackFlash:0,
  _harvestCooldownTimer:0,
  _harvestCooldownMax:0,
  _rodTier:0,           // 0=bamboo 1=cane 2=copper 3=iron 4=gold
  _quickCookRecipe:null,
  // ── Character customization ──
  name:'Stranger',
  gender:'male',
  skinTone:0,
  hairStyle:0,
  hairColor:0,
  shirtStyle:0,
  shirtColor:0,
  pantsColor:0,
