};

let _typeInterval   = null;

function showControlsIfNeeded() {
  if (localStorage.getItem(CONTROLS_SEEN_KEY)) return;
  const overlay = document.getElementById('controlsOverlay');
  if (overlay) overlay.classList.add('show');
}

function showMsg(txt, dur=2800) {
  _msgQueue.push({ txt, dur, isTip: false });
  if (!_msgShowing) _pumpMsgQueue();
}

function dSound(type) {
  if (!_soundEnabled) return;
  try {
    const ctx = getDahCtx();
    const t   = ctx.currentTime;
    const vol = _soundVol;

    switch(type) {
      case 'step': {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = 'sine'; o.frequency.value = 80 + Math.random()*20;
        g.gain.setValueAtTime(0.04*vol, t);
        g.gain.exponentialRampToValueAtTime(0.001, t+.08);
        o.start(t); o.stop(t+.08); break;
      }
      case 'tool': {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = 'square'; o.frequency.setValueAtTime(220, t);
        o.frequency.exponentialRampToValueAtTime(110, t+.08);
        g.gain.setValueAtTime(0.07*vol, t);
        g.gain.exponentialRampToValueAtTime(0.001, t+.12);
        o.start(t); o.stop(t+.12); break;
      }
      case 'harvest': {
        [440,550,660].forEach((f,i) => {
          const o=ctx.createOscillator(); const g=ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type='triangle'; o.frequency.value=f;
          g.gain.setValueAtTime(0.06*vol, t+i*.05);
          g.gain.exponentialRampToValueAtTime(0.001, t+i*.05+.15);
          o.start(t+i*.05); o.stop(t+i*.05+.15);
        }); break;
      }
      case 'sell': {
        [523,659,784].forEach((f,i) => {
          const o=ctx.createOscillator(); const g=ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type='sine'; o.frequency.value=f;
          g.gain.setValueAtTime(0.08*vol, t+i*.07);
          g.gain.exponentialRampToValueAtTime(0.001, t+i*.07+.2);
          o.start(t+i*.07); o.stop(t+i*.07+.2);
        }); break;
      }
      case 'hit': {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type='sawtooth'; o.frequency.setValueAtTime(180,t);
        o.frequency.exponentialRampToValueAtTime(60,t+.1);
        g.gain.setValueAtTime(0.12*vol,t);
        g.gain.exponentialRampToValueAtTime(0.001,t+.12);
        o.start(t); o.stop(t+.12); break;
      }
      case 'hurt': {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type='sawtooth'; o.frequency.setValueAtTime(300,t);
        o.frequency.exponentialRampToValueAtTime(80,t+.2);
        g.gain.setValueAtTime(0.15*vol,t);
        g.gain.exponentialRampToValueAtTime(0.001,t+.25);
        o.start(t); o.stop(t+.25); break;
      }
      case 'buy': {
        const o=ctx.createOscillator(); const g=ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type='triangle'; o.frequency.setValueAtTime(440,t);
        o.frequency.setValueAtTime(660,t+.07);
        g.gain.setValueAtTime(0.07*vol,t);
        g.gain.exponentialRampToValueAtTime(0.001,t+.18);
        o.start(t); o.stop(t+.18); break;
      }
      case 'ui': {
        const o=ctx.createOscillator(); const g=ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type='sine'; o.frequency.value=660;
        g.gain.setValueAtTime(0.05*vol,t);
        g.gain.exponentialRampToValueAtTime(0.001,t+.1);
        o.start(t); o.stop(t+.1); break;
      }
      case 'night': {
        // Low ominous drone
        const o=ctx.createOscillator(); const g=ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type='sine'; o.frequency.setValueAtTime(60,t);
        o.frequency.linearRampToValueAtTime(40,t+1.5);
        g.gain.setValueAtTime(0,t);
        g.gain.linearRampToValueAtTime(0.12*vol,t+.4);
        g.gain.linearRampToValueAtTime(0,t+1.5);
        o.start(t); o.stop(t+1.5); break;
      }
      case 'dawn': {
        [330,440,550,660].forEach((f,i) => {
          const o=ctx.createOscillator(); const g=ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type='triangle'; o.frequency.value=f;
          g.gain.setValueAtTime(0.06*vol,t+i*.1);
          g.gain.exponentialRampToValueAtTime(0.001,t+i*.1+.3);
          o.start(t+i*.1); o.stop(t+i*.1+.35);
        }); break;
      }
      case 'victory': {
        const notes=[261,330,392,523,659,784,1047];
        notes.forEach((f,i) => {
          const o=ctx.createOscillator(); const g=ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type = i<3?'sawtooth':'triangle';
          o.frequency.value=f;
          g.gain.setValueAtTime(0,t+i*.12);
          g.gain.linearRampToValueAtTime(0.10*vol,t+i*.12+.05);
          g.gain.exponentialRampToValueAtTime(0.001,t+i*.12+.6);
          o.start(t+i*.12); o.stop(t+i*.12+.65);
        }); break;
      }
      case 'save': {
        [440,523].forEach((f,i) => {
          const o=ctx.createOscillator(); const g=ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.type='sine'; o.frequency.value=f;
          g.gain.setValueAtTime(0.05*vol,t+i*.08);
          g.gain.exponentialRampToValueAtTime(0.001,t+i*.08+.15);
          o.start(t+i*.08); o.stop(t+i*.08+.15);
        }); break;
      }
    }
  } catch(e) {}
}

const T = 32;

const CONTROLS_SEEN_KEY = 'dah_controls_seen';

const _msgQueue = [];

let _msgShowing = false;

function _pumpMsgQueue() {
  if (_msgQueue.length === 0) { _msgShowing = false; return; }
  _msgShowing = true;
  const next = _msgQueue.shift();
  const el = document.getElementById('msgBanner');
  if (next.isTip) el.classList.add('tip'); else el.classList.remove('tip');
  el.textContent = next.txt; el.style.opacity = '1';
  msgTimer2 = next.dur;
}

let _soundEnabled = true;

function getDahCtx() {
  if (!_dahAudioCtx) _dahAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  // Browsers suspend AudioContext until a user gesture — resume it on every call so
  // sounds work after the first interaction regardless of when the context was created
  if (_dahAudioCtx.state === 'suspended') _dahAudioCtx.resume();
  return _dahAudioCtx;
}

let _soundVol = 0.5;

let msgTimer2 = 0;

let _dahAudioCtx = null;

function runIntro() {
  const screen = document.getElementById('introScreen');
  const deco   = document.getElementById('introDeco');
  const textEl = document.getElementById('introText');
  screen.classList.add('show');

  // fade in cactus
  const t0 = setTimeout(() => { deco.classList.add('vis'); }, 100);
  _introTimers.push(t0);

  let beatStart = 900; // ms after intro shows

  INTRO_BEATS.forEach((beat, i) => {
    const t = setTimeout(() => {
      if (_introSkipped) return;
      typewriterInto(textEl, beat.text, 38);
    }, beatStart);
    _introTimers.push(t);
    // each beat waits for its own type time + pause
    beatStart += beat.text.replace(/\n/g,'').length * 38 + beat.pause;
  });

  // final: fade out and start game
  const tEnd = setTimeout(() => {
    if (_introSkipped) return;
    finishIntro();
  }, beatStart + 400);
  _introTimers.push(tEnd);

  // skip on Enter key
  function onKey(e) {
    if (e.code === 'Enter' || e.code === 'Space') { skipIntro(); window.removeEventListener('keydown', onKey); }
  }
  window.addEventListener('keydown', onKey);
  // store remover so skipIntro can also clean it up
  _introKeyRemover = onKey;
}
