```javascript
function generateWeeklyBills(currentDay) {
  const currentWeek = Math.min(getWeekNumber(currentDay), DEBT_TOTAL_WEEKS);
  for (let w = 1; w <= currentWeek; w++) {
    if (!weeklyBills.find(b => b.week === w)) {
      const amount = getWeeklyBillAmount(w);
      weeklyBills.push({ week: w, amount, due: (w - 1) * DEBT_WEEK_LENGTH + 1, paid: false });
      if (w > 1) {  // Don't announce week 1 on game start
        showMsg(`🏦 Week ${w} bank payment due: $${amount}!`);
      }
    }
  }
}

const gameState = {
  day:1, timeOfDay:6*60, dayLength:24*60, daySpeed:2.5,
  _noonProductsDespawned:false, _wiltChecked:false,
  isNight:false, zone:'Farm',
  camera:{x:0,y:0}, season:'Dry Summer', particles:[],
  stormActive:false, stormSheltering:false,
  _postEnding: false,
  _stormIntensity:0,      // 0.0–1.0 current visual/gameplay intensity
  _stormPhase:'none',     // 'none' | 'warning' | 'building' | 'peak' | 'fading'
  _stormTimer:0,          // seconds elapsed in current phase
  _stormPhaseDur:0,       // total seconds for current phase
  _stormWarnShown:false,  // warning message fired this storm
  _shelterTX:0, _shelterTY:0, // tile pos where manual shelter was chosen
  inMine:false, mineFloor:0, _deepestMineFloor:0,
  inBLMine:false, blMineFloor:0, // The Company Mine in the badlands
  _mineDread:0,            // 0–100 dread meter for dark floors
  _mineJournal:[],         // [{day, text, isSurveyor}] persistent mine log
  _mineLastHaul:{},        // {oreId:{flawed,standard,pure}} from last session
  _deepMapUsed:{},         // {floorKey:day} tracks deep-map one-use-per-floor-per-day
  _mineCoalSessions:0,     // tracks consecutive coal-mining sessions for blue coal unlock
  _activeBranch:null,      // current pending branch choice {node,key,fl,baseQty,lootId}
  _candleBurnLeft:0,       // seconds remaining on active beeswax candle
  _torchBurnLeft:90,       // seconds remaining on current torch (resets per torch)
  inBadlands:false,
  inHoboCamp:false,
  inOcean:false,
  boatX: 24*32, boatY: 38*32,
  boatVX:0, boatVY:0,
  pirateHeat: 0,   // 0-5: escalates with pirate kills, resets each night
};

function refreshDebtHUD() {
  const el = document.getElementById('debtDisp');
  if (!el) return;
  const debt = getTotalDebt();
  if (debt <= 0 && weeklyBills.length >= DEBT_TOTAL_WEEKS) {
    el.textContent = '🏦 DEBT FREE';
    el.style.color = '#60d040';
    el.style.borderColor = 'rgba(60,200,40,.5)';
  } else if (debt <= 0 && weeklyBills.length > 0) {
    el.textContent = '🏦 Paid ahead';
    el.style.color = '#90c060';
    el.style.borderColor = 'rgba(100,160,40,.4)';
  } else {
    el.textContent = `🏦 $${debt.toLocaleString()}`;
    const nextWeek = getWeekNumber(gameState.day) + 1;
    if (nextWeek <= DEBT_TOTAL_WEEKS) {
      const nextBill = getWeeklyBillAmount(nextWeek);
      el.title = `Next bill (Week ${nextWeek}): $${nextBill}`;
    } else {
      el.title = 'Final week — clear your balance';
    }
    el.style.color  = debt > 500 ? '#e07050' : debt > 200 ? '#d0a030' : '#80d060';
    el.style.borderColor = debt > 500 ? 'rgba(200,60,40,.4)' : debt > 200 ? 'rgba(200,160,40,.4)' : 'rgba(60,200,40,.4)';
  }
  // Also keep the debt clock widget in sync
  if (typeof updateDebtClock === 'function') updateDebtClock();
}

function getWeekNumber(day) {
  return Math.floor((day - 1) / DEBT_WEEK_LENGTH) + 1;
}

const DEBT_TOTAL_WEEKS   = 24;

let weeklyBills = [];

function getWeeklyBillAmount(week) {
  const dm = getDifficultyConfig().debtMult || 1.0;
  const base = Math.round((DEBT_WEEKLY_BASE + (week - 1) * DEBT_WEEKLY_STEP) * dm);
  // Vera's case: mineral rights complaint reduces each bill by $50
  return player._veraDebtReduction ? Math.max(0, base - 50) : base;
}

const DEBT_WEEK_LENGTH   = 7;

function showMsg(txt, dur=2800) {
  _msgQueue.push({ txt, dur, isTip: false });
  if (!_msgShowing) _pumpMsgQueue();
}

function getTotalDebt() {
  return weeklyBills.filter(b => !b.paid).reduce((s, b) => s + b.amount, 0);
}

function updateDebtClock() {
  const clock = document.getElementById('debtClock');
  if (!clock) return;
  generateWeeklyBills(gameState.day);
  const debt = getTotalDebt();
  const amtEl = document.getElementById('debtClockAmt');
  const nextEl = document.getElementById('debtClockNext');
  const fill   = document.getElementById('debtClockFill');

  if (debt <= 0 && weeklyBills.length > 0) {
    amtEl.textContent = 'PAID IN FULL';
    amtEl.classList.add('clear');
    nextEl.textContent = '';
    if (fill) fill.style.width = '0%';
  } else {
