  if (gameState.stormSheltering) {
    if (!gameState._shelterTX) { gameState._shelterTX = tx; gameState._shelterTY = ty; }
    if (Math.abs(tx - gameState._shelterTX) > 3 || Math.abs(ty - gameState._shelterTY) > 3) {
