function plotKey(tx,ty){ return tx+','+ty; }

const plots = {};

function setT(x,y,t){ if(x>=0&&x<MAP_W&&y>=0&&y<MAP_H){ tileMap[y*MAP_W+x]=t; _minimapCacheDirty=true; } }

const TL = { GRASS:0, DIRT:1, STONE:2, WATER:3, SAND:4, ROAD:5,
