};

const T = 32;

let enemies = [];

let pens = [];

function getAnimalById(id) { return animals.find(a => a.id === id); }

const player = {
  x:17*T+T/2, y:26*T+T/2,
  speed:112, sprintMult:1.75,
  hp:100, maxHp:100,
  stamina:100, maxStamina:100, staminaRegen:14,
