  ctx.fillStyle='#786030'; ctx.fillRect(sx-4,sy-23+bob,8,2);
  ctx.fillStyle='#988050'; ctx.fillRect(sx-4,sy-23+bob,4,1);

  // Cap — simple peaked work cap, not naval dress
