  // Sparse wind — single buffer
  try {
    if (Math.random() > 0.3) {
      const wc=bgmCtx(), ws=Math.floor(wc.sampleRate*BAR*3);
      const wb=wc.createBuffer(1,ws,wc.sampleRate), wd=wb.getChannelData(0);
