      const startBar=Math.floor(Math.random()*(BARS-3));
      wsrc.start(t+startBar*BAR); wsrc.stop(t+startBar*BAR+BAR*3+0.1);
    }
  } catch(e) {}

  const dur = BARS*BAR;
  BGM.seqTimer = setTimeout(()=>scheduleHoboLoop(t+dur), (dur-0.4)*1000);
}
