          g.gain.setValueAtTime(0.08*vol, t+i*.07);
          g.gain.exponentialRampToValueAtTime(0.001, t+i*.07+.2);
          o.start(t+i*.07); o.stop(t+i*.07+.2);
        }); break;
      }
