let exploredWorld = new Uint8Array(MAP_W * MAP_H);

let exploredMine  = null;

let exploredHobo = new Uint8Array(HC_W * HC_H);

function revealAround(px, py, radius, grid, gw, gh) {
  const tx = Math.floor(px / T);
  const ty = Math.floor(py / T);
  const r2 = radius * radius;
  let revealed = false;
  for (let dy = -radius; dy <= radius; dy++) {
    for (let dx = -radius; dx <= radius; dx++) {
      if (dx*dx + dy*dy > r2) continue;
      const nx = tx + dx, ny = ty + dy;
      if (nx < 0 || nx >= gw || ny < 0 || ny >= gh) continue;
      if (!grid[ny * gw + nx]) {
        grid[ny * gw + nx] = 1;
        revealed = true;
      }
    }
  }
  if (revealed) _minimapCacheDirty = true;
}

const player = {
  x:17*T+T/2, y:26*T+T/2,
  speed:112, sprintMult:1.75,
  hp:100, maxHp:100,
  stamina:100, maxStamina:100, staminaRegen:14,
  gold:120,
  debt:0,             // legacy field — debt now tracked via weeklyBills
  w:18, h:18,
  sprinting:false,
  facing:'down', walkFrame:0, walkTimer:0,
  tool:'till', selectedSeed:'carrot',
  actionCooldown:0,
  attackCooldown:0,
  invincibleTimer:0,
  attackFlash:0,
  _harvestCooldownTimer:0,
  _harvestCooldownMax:0,
};

const WORLD_REVEAL_RADIUS = 5;

const MAP_W=80;

const MAP_H=80;

let _minimapCacheDirty = true;

const HC_W = 60;

const HC_H = 50;

const T = 32;

function initFog() {
  exploredWorld.fill(0);
  exploredMine.forEach(g => g.fill(0));
  exploredHobo.fill(0);
  // Pre-reveal spawn area and full farm zone on minimap
  revealAround(player.x, player.y, WORLD_REVEAL_RADIUS + 2, exploredWorld, MAP_W, MAP_H);
  // Mark all farm tiles and a buffer around them as explored
  for (let ty = 0; ty <= 34; ty++) {
    for (let tx = 0; tx <= 34; tx++) {
      exploredWorld[ty * MAP_W + tx] = 1;
    }
  }
  _minimapCacheDirty = true;
}
