const economy = {
  prices:     resetPrices(),
  seedPrices: { carrot:3, corn:7, pumpkin:14, glowroot:28, tomato:5, dustwheat:11, sunblossom:40, pepper:4, melon:18, potato:4, lavender:15, cactusFruit:12, blueberry:3, garlic:4, strawberry:8, onion:6, watermelon:22, rosehip:18, moonshroom:14 },
