function refreshFarmhandUI() {
  // Count work available
  const plotList = Object.values(plots);
  const needWater   = plotList.filter(p => p.tilled && p.crop && !p.wateredToday && !p.harvestReady && !p.wilted).length;
  const readyToHarv = plotList.filter(p => p.harvestReady).length;
  const wiltedCount = plotList.filter(p => p.wilted).length;
  const untilledFarm = (() => {
    let n = 0;
    for (let ty = 3; ty <= 21; ty++) for (let tx = 3; tx <= 21; tx++) {
      if (!isFarmTile(tx,ty)) continue;
      const k = plotKey(tx,ty);
      if (!plots[k] || !plots[k].tilled) n++;
    }
    return n;
  })();

  const waterCost  = Math.max(5, needWater * 4);
  const harvCost   = Math.max(5, readyToHarv * 6);
  const tillCost   = Math.max(10, Math.min(untilledFarm, 20) * 3);
  const reviveCost = Math.max(8, wiltedCount * 8);

  // Tip line
  const tips = [];
  if (needWater)   tips.push(`${needWater} plot${needWater>1?'s':''} need watering`);
  if (readyToHarv) tips.push(`${readyToHarv} ready to harvest`);
  if (wiltedCount) tips.push(`${wiltedCount} wilted crop${wiltedCount>1?'s':''}`);
  document.getElementById('farmhandTip').textContent =
    tips.length ? `I can see: ${tips.join(', ')}.` : 'Everything looks good out there. Nothing for me to do right now.';

  const jobs = [
    {
      icon:'💧', name:'Water all crops',
      desc: needWater ? `${needWater} plot${needWater>1?'s':''} need watering today` : 'All crops already watered',
      cost: waterCost, disabled: needWater === 0,
      action: 'farmhandDoWater()',
    },
    {
      icon:'🌾', name:'Harvest ready crops',
      desc: readyToHarv ? `${readyToHarv} crop${readyToHarv>1?'s':''} ready to collect` : 'Nothing ready to harvest yet',
      cost: harvCost, disabled: readyToHarv === 0,
      action: 'farmhandDoHarvest()',
    },
    {
      icon:'⛏', name:'Till all farm plots',
      desc: untilledFarm ? `${Math.min(untilledFarm,20)} untilled plot${untilledFarm>1?'s':''} (up to 20)` : 'All plots already tilled',
      cost: tillCost, disabled: untilledFarm === 0,
      action: 'farmhandDoTill()',
    },
    {
      icon:'🌱', name:'Revive wilted crops',
      desc: wiltedCount ? `${wiltedCount} wilted crop${wiltedCount>1?'s':''} — saves them from dying` : 'No wilted crops right now',
      cost: reviveCost, disabled: wiltedCount === 0,
      action: 'farmhandDoRevive()',
    },
  ];

  let h = '';
  for (const job of jobs) {
    const canAfford = player.gold >= job.cost;
    const off = job.disabled || !canAfford;
    h += `<div class="fh-job">
      <span style="font-size:18px">${job.icon}</span>
      <div class="fh-job-info">
        <div class="fh-job-name">${job.name}</div>
        <div class="fh-job-desc">${job.desc}</div>
      </div>
      <span class="fh-job-cost">$${job.cost}</span>
      <button class="fh-hire-btn" onclick="${job.action}" ${off?'disabled':''}>HIRE</button>
    </div>`;
  }
  document.getElementById('farmhandJobs').innerHTML = h;
}

const T = 32;

let msgTimer2 = 0;

const MAP_W=80;

const MAP_H=80;

const tileMap = new Uint8Array(MAP_W*MAP_H);

let _minimapCacheDirty = true;

function isFarmTile(tx,ty) {
  // Any dirt tile inside the farm fence (x=2..32, y=2..32) is farmable,
  // as long as it's not occupied by a solid structure or placed feature.
  if (tx < 2 || tx > 32 || ty < 2 || ty > 32) return false;
  const t = getT(tx, ty);
  if (SOLID.has(t)) return false;
  if (t === TL.BUILDING || t === TL.ROAD || t === TL.CAMPFIRE) return false;
  return true;
}

function plotKey(tx,ty){ return tx+','+ty; }

function getT(x,y){ if(x<0||x>=MAP_W||y<0||y>=MAP_H) return TL.STONE; return tileMap[y*MAP_W+x]; }

const SOLID = new Set([2,3,9,10,11,14,15,16,19,20,21,22,28,37,38,42]);

function farmhandDoRevive() {
  const targets = Object.entries(plots).filter(([,p]) => p.wilted);
  const cost = Math.max(8, targets.length * 8);
  if (player.gold < cost) { showMsg(`⚠️ Need $${cost} to hire.`); return; }
  player.gold -= cost;
  let done = 0;
  for (const [k, p] of targets) {
    p.wilted = false; p.watered = true; p.wateredToday = true; p.growthProgress = Math.max(0, p.growthProgress - 0.1);
    const [tx,ty] = k.split(',').map(Number);
    setT(tx, ty, TL.FARM_WATERED);
    done++;
  }
  showMsg(`🧑‍🌾 Jed revived ${done} wilted crop${done>1?'s':''}. ($${cost} paid)`);
  refreshFarmhandUI();
}
