};

const T = 32;

function getMineT(floor, x, y) {
  if (x < 0 || x >= MINE_W || y < 0 || y >= MINE_H) return TL.MINE_WALL;
  return mineFloorMaps[floor][y * MINE_W + x];
}

const MINE_W = 48;

const MINE_H = 48;

const TL = { GRASS:0, DIRT:1, STONE:2, WATER:3, SAND:4, ROAD:5,
  FARM_DRY:6, FARM_TILLED:7, FARM_WATERED:8, BUILDING:9, WALL:10,
  TREE:11, MINE:12, SIGN:13, DEEP_WATER:14, BUSH:15, ROCK:16,
  FLOWERS:17, TOWN_FLOOR:18, CRATE:19, FENCE:20, WELL:21,
  BARN_CLOSED:22, BARN_OPEN:23, FENCE_GATE:24, FEED_TROUGH:25, PEN_FLOOR:26,
  // Mine interior tiles
  MINE_FLOOR:27, MINE_WALL:28, COAL_VEIN:29, COPPER_VEIN:30,
  IRON_VEIN:31, GOLD_VEIN:32, CRYSTAL_VEIN:33, MINE_EXIT:34, MINE_SHAFT_DOWN:35, MINE_SHAFT_UP:36,
  WORKBENCH:37, FORGE:38, FISHING_SPOT:39, CAMPFIRE:40, BADLANDS_PORTAL:41, SPRINKLER:42,
  // Floor 4 — The Unmapped
  SILVER_VEIN:43, SINGING_VEIN:44, HIDDEN_SHAFT:45, HOBO_PORTAL:46, OCEAN_PORTAL:47 };

const mineFloorMaps = [
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H), // Floor 4 — The Unmapped
];

function getMineNearbyNode() {
  if (!gameState.inMine) return null;
  const fl = gameState.mineFloor;
  const nodes = mineResourceNodes[fl];
  const px = Math.floor(player.x/T), py = Math.floor(player.y/T);
  const nodeOffs = { down:[0,1], up:[0,-1], left:[-1,0], right:[1,0] };
  const [ox,oy] = nodeOffs[player.facing]||[0,1];
  const orderedChecks = [
    [px+ox, py+oy], [px+ox*2, py+oy*2], [px,py],
    [px+1,py],[px-1,py],[px,py+1],[px,py-1],
    [px+1,py+1],[px-1,py-1],[px+1,py-1],[px-1,py+1],
  ];
  for (const [cx,cy] of orderedChecks) {
    const key = cx+','+cy;
    const node = nodes[key];
    if (!node || node.depleted) continue;
    if (getMineT(fl, cx, cy) !== node.def.tile) { node.depleted = true; continue; }
    return { key, node };
  }
  return null;
}
