function getHCT(x,y){ if(x<0||x>=HC_W||y<0||y>=HC_H) return TL.STONE; return hcMap[y*HC_W+x]; }

const TL = { GRASS:0, DIRT:1, STONE:2, WATER:3, SAND:4, ROAD:5,
