function drawBLTile(tx,ty,sx,sy) {
  const t=getBLT(tx,ty);
  const c=BL_TC[t]||BL_TC[BL.CRACKED];
  ctx.fillStyle=c[0]; ctx.fillRect(sx,sy,T,T);

  if(t===BL.CRACKED) {
    ctx.strokeStyle=c[1]; ctx.lineWidth=1;
    // Crack lines — stable per tile
    const s0=(tx*7+ty*13)%8;
    ctx.beginPath(); ctx.moveTo(sx+4+s0,sy+8); ctx.lineTo(sx+T-6,sy+T-10); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(sx+T-8,sy+4); ctx.lineTo(sx+6,sy+T-6); ctx.stroke();
  } else if(t===BL.REDROCK) {
    ctx.fillStyle=c[1]; ctx.fillRect(sx+3,sy+3,T-6,T-6);
    ctx.fillStyle='#d06040'; ctx.fillRect(sx+6,sy+6,6,4); ctx.fillRect(sx+T-10,sy+T-8,5,3);
  } else if(t===BL.DUSTFLOOR) {
    if((tx+ty)%4===0){ctx.fillStyle='rgba(180,160,100,.3)';ctx.fillRect(sx+8,sy+4,3,2);}
  } else if(t===BL.MESA) {
    ctx.fillStyle='#d06030'; ctx.fillRect(sx+2,sy+2,T-4,T-4);
    ctx.fillStyle='#702810'; ctx.fillRect(sx+4,sy+4,T-8,T-8);
