    // Crack line
    ctx.strokeStyle='#2a2020'; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(sx+T/2,sy+T/2-1); ctx.lineTo(sx+T/2-2,sy+T/2+7); ctx.stroke();
    // Teeth-like bottom edge
    ctx.fillStyle='#484040';
    ctx.fillRect(sx+T/2-5,sy+T/2+4,3,4); ctx.fillRect(sx+T/2,sy+T/2+4,3,4);
  } else if(t===BL.SULFUR) {
    ctx.fillStyle='#e8d040'; for(let i=0;i<3;i++) ctx.fillRect(sx+4+i*8,sy+T/2-3,6,6);
  } else if(t===BL.TUMBLEWEED) {
    ctx.fillStyle='#b09858'; ctx.beginPath(); ctx.arc(sx+T/2,sy+T/2,9,0,Math.PI*2); ctx.fill();
