    if(t===BL.OUTPOST_WALL){ctx.fillStyle='#5a2810';ctx.fillRect(sx+2,sy+2,T-4,T-4);}
    else{ctx.fillStyle='#7a5040';ctx.fillRect(sx,sy,T,T);ctx.fillStyle='#6a4030';if((tx+ty)%2===0)ctx.fillRect(sx+4,sy+4,T-8,T-8);}
  } else if(t===BL.BL_BONE) {
    ctx.fillStyle='#e0d8c0'; ctx.fillRect(sx+5,sy+T/2-3,T-10,5);
    ctx.fillRect(sx+T/2-3,sy+5,5,T-10);
  } else if(t===BL.BL_COPPER) {
    ctx.fillStyle='#8a4820'; ctx.fillRect(sx+4,sy+4,T-8,T-8);
