    ctx.fillStyle='#0a1204';
    ctx.beginPath(); ctx.ellipse(sx+T/2,sy+T/2+4,4,3,0,0,Math.PI*2); ctx.fill();
    // Rising gas bubbles
    for(let b=0;b<3;b++){
      const bx=sx+8+b*7;
      const by=sy+T/2-2+Math.sin(bub+b)*4;
      const ba=0.5+0.3*Math.sin(bub+b*1.5);
      ctx.fillStyle=`rgba(140,210,20,${ba})`;
      ctx.beginPath(); ctx.arc(bx,by,2+Math.sin(bub+b),0,Math.PI*2); ctx.fill();
    }
    // Sulfur crust ring
    ctx.strokeStyle='rgba(180,200,20,.4)'; ctx.lineWidth=1;
    ctx.beginPath(); ctx.ellipse(sx+T/2,sy+T/2+4,8,5,0,0,Math.PI*2); ctx.stroke();
  } else if(t===BL.SETTLEMENT) {
    // Worn stone floor of ruined settlement
    ctx.fillStyle='#504038'; ctx.fillRect(sx,sy,T,T);
    ctx.fillStyle='#3e3028'; if((tx+ty*2)%3===0) ctx.fillRect(sx+2,sy+2,T-4,T-4);
  } else if(t===BL.SETTLEMENT_WALL) {
