    ctx.fillStyle='#302018'; ctx.fillRect(sx,sy,T,T);
    ctx.fillStyle='#3e2c18'; ctx.fillRect(sx+2,sy+2,T-4,T-4);
    // Stone texture
    ctx.fillStyle='rgba(80,60,30,.4)'; ctx.fillRect(sx+4,sy+8,T-8,3); ctx.fillRect(sx+4,sy+18,T-8,3);
    ctx.fillStyle='rgba(60,40,20,.3)'; ctx.fillRect(sx+T/2,sy+2,2,T-4);
  }
