  prices:     { carrot:14, corn:34, pumpkin:68, glowroot:140, tomato:25, dustwheat:55, sunblossom:200, stone:6, wood:10, herb:20, egg:12, wool:28, milk:45, banditScarf:30, wolfPelt:45, burrowerCarapace:22, raiderBadge:90, snakeFang:18, coal:12, copperOre:28, ironOre:55, goldOre:130, crystal:280, copperBar:72, ironBar:145, goldBar:340, torch:8 },
  seedPrices: { carrot:3, corn:7, pumpkin:14, glowroot:28, tomato:5, dustwheat:11, sunblossom:40 },
  mult:       { carrot:1, corn:1, pumpkin:1, glowroot:1, tomato:1, dustwheat:1, sunblossom:1, stone:1, wood:1, herb:1, egg:1, wool:1, milk:1, banditScarf:1, wolfPelt:1, burrowerCarapace:1, raiderBadge:1, snakeFang:1, woolBlanket:1, copperFitting:1, ironSpike:1, leatherStrip:1, plank:1, rope:1, cloth:1 },
  event: null, evDaysLeft: 0,
  hist: { carrot:[], corn:[], pumpkin:[], glowroot:[], tomato:[], dustwheat:[], sunblossom:[], stone:[], wood:[], herb:[], egg:[], wool:[], milk:[], banditScarf:[], wolfPelt:[], burrowerCarapace:[], raiderBadge:[], snakeFang:[], woolBlanket:[], copperFitting:[], ironSpike:[], leatherStrip:[], plank:[], rope:[], cloth:[] },
};

const BASE_PRICES = { carrot:14, corn:34, pumpkin:68, glowroot:140, tomato:25, dustwheat:55, sunblossom:200, stone:6, wood:10, herb:20, egg:12, wool:28, milk:45, banditScarf:30, wolfPelt:45, burrowerCarapace:22, raiderBadge:90, snakeFang:18, coal:12, copperOre:28, ironOre:55, goldOre:130, crystal:280, copperBar:72, ironBar:145, goldBar:340, torch:8, woolBlanket:90, copperFitting:55, ironSpike:48, leatherStrip:38, plank:8, rope:22, cloth:18 };

function renderHistory(body) {
  const items = [
    {id:'carrot',name:'Carrot',icon:'🥕'},{id:'corn',name:'Corn',icon:'🌽'},
    {id:'pumpkin',name:'Pumpkin',icon:'🎃'},{id:'glowroot',name:'Glowroot',icon:'✨'},
  ];
  let h = `<div style="font-size:9px;color:#6a5020;margin-bottom:10px">PRICE HISTORY — last 10 days</div>`;
  for (const item of items) {
    const hist = economy.hist[item.id] || [];
    const cur  = economy.prices[item.id];
    const all  = [...hist, cur];
    const mx   = Math.max(...all, 1);
    const W=220, H=40;
    let pts = '';
    all.forEach((p,i) => { const x=i/(all.length-1||1)*W; const y=H-(p/mx*H*.9); pts+=(i===0?'M':'L')+x.toFixed(1)+','+y.toFixed(1); });
    const col = cur>(BASE_PRICES[item.id]||1)*1.1 ? '#60e060' : cur<(BASE_PRICES[item.id]||1)*.9 ? '#e06060' : '#d4b870';
    h += `<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;padding:7px;background:rgba(255,255,255,.02);border-radius:3px;">
      <span style="font-size:14px;width:20px">${item.icon}</span>
      <span style="font-size:10px;color:#c0a060;width:60px">${item.name}</span>
      <svg width="${W}" height="${H}" style="flex-shrink:0"><path d="${pts}" stroke="${col}" stroke-width="1.5" fill="none"/></svg>
      <span style="font-size:11px;color:${col};min-width:34px;text-align:right">$${cur}</span>
    </div>`;
  }
  body.innerHTML = h;
}
