const MINE_W = 48;

const MINE_H = 48;

const mineFloorMaps = [
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
  new Uint8Array(MINE_W * MINE_H),
];

const MAP_W=80;

