function hasPickaxe() { return PICKAXE_IDS.some(id => purchasedUpgrades.has(id)); }

function hasAxe()     { return AXE_IDS.some(id => purchasedUpgrades.has(id)); }

const PICKAXE_IDS = ['pick_stone','pick_copper','pick_tin','pick_gold','pick_iron'];

const purchasedUpgrades = new Set();

const AXE_IDS     = ['axe_stone','axe_copper','axe_tin','axe_gold','axe_iron'];

function checkToolForNode(nodeDef) {
  const loot = nodeDef.loot;
  if (loot === 'stone') {
    if (!hasPickaxe()) return { ok:false, msg:'⛏ You need a Pickaxe to mine stone — buy one at the market [M] → Upgrades.' };
  }
  if (loot === 'wood') {
    if (!hasAxe()) return { ok:false, msg:'🪓 You need an Axe to chop wood — buy one at the market [M] → Upgrades.' };
  }
  // herbs: any tool/item is fine
  return { ok:true };
}
