    const nearby = getMineNearbyNode();
    if (nearby) {
      const def = nearby.node.def;
      const mult = getEffectiveMiningMult(def.loot);
      const multStr = mult > 1 ? ` <span style="color:#80e060">×${mult}</span>` : '';
      const toolCheck = checkToolForNode(def);
      if (!toolCheck.ok) {
