const SEASONS = [
  { name:'Dry Summer',  icon:'☀️',  days:10, cropMult:1.0,  enemyMult:1.0,  priceBonus:{tomato:.3,snakeFang:.2},                             color:'#e0a020', desc:'Hot and dry. Standard conditions.' },
  { name:'Harvest Fall',icon:'🍂',  days:10, cropMult:1.3,  enemyMult:1.2,  priceBonus:{carrot:.2,corn:.3,pumpkin:.5,tomato:.2,dustwheat:.4},  color:'#c06020', desc:'Crops grow faster. Good time to harvest.' },
