function generateWeeklyBills(currentDay) {
  const currentWeek = getWeekNumber(currentDay);
  for (let w = 1; w <= currentWeek; w++) {
    if (!weeklyBills.find(b => b.week === w)) {
      const amount = getWeeklyBillAmount(w);
      weeklyBills.push({ week: w, amount, due: (w - 1) * DEBT_WEEK_LENGTH + 1, paid: false });
      if (w > 1) {  // Don't announce week 1 on game start
        showMsg(`🏦 Week ${w} bank payment due: $${amount}!`);
      }
    }
  }
}

const gameState = {
  day:1, timeOfDay:6*60, dayLength:24*60, daySpeed:2.5,
  isNight:false, zone:'Farm',
  camera:{x:0,y:0}, season:'Dry Summer', particles:[],
  stormActive:false, stormSheltering:false,
  inMine:false, mineFloor:0,
};

function getTotalDebt() {
  return weeklyBills.filter(b => !b.paid).reduce((s, b) => s + b.amount, 0);
}

let weeklyBills = [];

function getWeekNumber(day) {
  return Math.floor((day - 1) / DEBT_WEEK_LENGTH) + 1;
}

const DEBT_WEEK_LENGTH   = 7;

function getWeeklyBillAmount(week) {
  return DEBT_WEEKLY_BASE + (week - 1) * DEBT_WEEKLY_STEP;
}

function showMsg(txt, dur=2800) {
  const el = document.getElementById('msgBanner');
  el.textContent=txt; el.style.opacity='1'; msgTimer2=dur;
}

const DEBT_WEEKLY_BASE   = 100;

const DEBT_WEEKLY_STEP   = 10;

let msgTimer2 = 0;

function updateDebtClock() {
  const clock = document.getElementById('debtClock');
  if (!clock) return;
  generateWeeklyBills(gameState.day);
  const debt = getTotalDebt();
  const amtEl = document.getElementById('debtClockAmt');
  const nextEl = document.getElementById('debtClockNext');
  const fill   = document.getElementById('debtClockFill');

  if (debt <= 0 && weeklyBills.length > 0) {
    amtEl.textContent = 'PAID IN FULL';
    amtEl.classList.add('clear');
    nextEl.textContent = '';
    if (fill) fill.style.width = '0%';
  } else {
    amtEl.textContent = '$' + debt.toLocaleString();
    amtEl.classList.remove('clear');

    // Days until next bill
    const currentWeek  = getWeekNumber(gameState.day);
    const nextWeek     = currentWeek + 1;
    const nextBillDay  = (nextWeek - 1) * DEBT_WEEK_LENGTH + 1;
    const daysLeft     = nextBillDay - gameState.day;
    const nextAmt      = getWeeklyBillAmount(nextWeek);
    nextEl.textContent = `+$${nextAmt} in ${daysLeft}d`;

    // Fill bar: week progress
    const weekPct = ((gameState.day - 1) % DEBT_WEEK_LENGTH) / DEBT_WEEK_LENGTH * 100;
    if (fill) fill.style.width = weekPct + '%';
  }
}
