function drawPlayer(cx,cy){
  const p=S.player;
  const sx=(p.x-cx)|0, sy=(p.y-cy)|0+HH;
  if(p.inv>0&&Math.floor(p.inv/4)%2===1) return;
  const cr=p.curse/p.maxCurse;
  const bodyC=cr>0.7?C.DKPUR:C.MIDGRY;
  const capeC=cr>0.7?'#3d0035':C.DKRED;
  const skinC=cr>0.7?'#8a5858':C.SKIN;
  const eyeC=cr>0.5?'#ff0033':'#000';
