  GC.fillStyle='rgba(0,0,0,0.4)'; GC.fillRect(sx+3,sy+13,10,3);
  // cape
  GC.fillStyle=capeC; GC.fillRect(sx+3,sy+6,10,9);
  // body
  GC.fillStyle=bodyC; GC.fillRect(sx+4,sy+7,8,7);
  // head
  GC.fillStyle=skinC; GC.fillRect(sx+4,sy+2,8,6);
  // hood
  GC.fillStyle='#161616'; GC.fillRect(sx+3,sy,10,4); GC.fillRect(sx+2,sy+2,12,2);
  // eyes
  GC.fillStyle=eyeC;
  if(p.facing===2){GC.fillRect(sx+5,sy+4,2,2);GC.fillRect(sx+9,sy+4,2,2);}
  else if(p.facing===0){GC.fillRect(sx+5,sy+3,2,1);GC.fillRect(sx+9,sy+3,2,1);}
  else if(p.facing===1){GC.fillRect(sx+9,sy+4,2,2);}
  else{GC.fillRect(sx+5,sy+4,2,2);}
  // legs walk anim
  const wf=p.walkF;
  GC.fillStyle=bodyC;
  if(wf===0){GC.fillRect(sx+4,sy+13,4,3);GC.fillRect(sx+8,sy+13,4,3);}
  else if(wf===1){GC.fillRect(sx+3,sy+12,4,4);GC.fillRect(sx+9,sy+14,4,2);}
  else if(wf===2){GC.fillRect(sx+4,sy+13,4,3);GC.fillRect(sx+8,sy+13,4,3);}
  else{GC.fillRect(sx+4,sy+14,4,2);GC.fillRect(sx+10,sy+12,4,4);}
  // weapon swing arc
  if(p.atkT>0){
    const prog=1-(p.atkT/p.atkDur);
    const wlen=(prog*14)|0;
    const wid=p.weapon===2?5:p.weapon===3?6:3;
    GC.fillStyle=p.weapon===2?C.GOLD:p.weapon===3?C.SILV:C.LTGRY;
    if(p.facing===2){GC.fillRect(sx+12,sy+6,wid,wlen);}
    else if(p.facing===0){GC.fillRect(sx+12,sy+8-wlen,wid,wlen);}
    else if(p.facing===1){GC.fillRect(sx+13,sy+7,wlen,wid);}
    else{GC.fillRect(sx-wlen+3,sy+7,wlen,wid);}
  }
  // lantern
  if(p.lantern&&p.oil>0){
    const lo=Math.floor(S.fc/12)%2;
    GC.fillStyle=lo?C.AMBRE:C.GOLD;
    GC.fillRect(sx-3,sy+7,3,5);
    GC.fillStyle=lo?C.FLAME:C.AMBRE;
    GC.fillRect(sx-2,sy+6,2,2);
  }
}
