function drawNPC(npc,cx,cy){
  const sx=(npc.x-cx)|0, sy=(npc.y-cy)|0+HH;
  if(sx<-20||sx>W+20||sy<HH||sy>H+20) return;
  const bob=(Math.sin(S.fc*0.05)*1)|0;
  switch(npc.id){
    case 'priest':
      GC.fillStyle='#e0e0d0'; GC.fillRect(sx+3,sy+7+bob,10,9);
      GC.fillStyle=C.SKIN; GC.fillRect(sx+4,sy+2+bob,8,6);
      GC.fillStyle='#c8c8b8'; GC.fillRect(sx+2,sy+1+bob,12,5);
      GC.fillStyle='#888800'; GC.fillRect(sx+6,sy+4+bob,4,4); // stole
      GC.fillStyle=C.DKRED; GC.fillRect(sx+7,sy+4+bob,2,3);
      // suspicious eyes
      GC.fillStyle='#660000'; GC.fillRect(sx+5,sy+3+bob,2,2); GC.fillRect(sx+9,sy+3+bob,2,2);
      // staff
      GC.fillStyle=C.BRN; GC.fillRect(sx+15,sy+2+bob,2,14);
      GC.fillStyle=C.GOLD; GC.fillRect(sx+14,sy+1+bob,4,3);
      break;
    case 'smith':
      GC.fillStyle='#333333'; GC.fillRect(sx+3,sy+7+bob,10,9);
      GC.fillStyle=C.SKIN; GC.fillRect(sx+4,sy+2+bob,8,6); // head
      // beard
      GC.fillStyle='#554433'; GC.fillRect(sx+4,sy+6+bob,8,3);
      // apron
      GC.fillStyle='#5c3010'; GC.fillRect(sx+4,sy+8+bob,8,8);
      GC.fillStyle='#888888'; GC.fillRect(sx+6,sy+10+bob,4,6);
      // arms
      GC.fillStyle=C.SKIN; GC.fillRect(sx+0,sy+7+bob,4,7); GC.fillRect(sx+12,sy+7+bob,4,7);
      // hammer
      GC.fillStyle=C.SILV; GC.fillRect(sx+14,sy+8+bob,5,3);
      GC.fillStyle=C.BRN; GC.fillRect(sx+15,sy+10+bob,2,5);
      // blood mouth on day 2+
      if(S.flags.day2){GC.fillStyle=C.BLOOD;GC.fillRect(sx+5,sy+6+bob,6,2);}
      // dark eyes
      GC.fillStyle='#000'; GC.fillRect(sx+5,sy+3+bob,2,2); GC.fillRect(sx+9,sy+3+bob,2,2);
      break;
    case 'child':
      // small sprite
      GC.fillStyle=C.SKIN; GC.fillRect(sx+5,sy+4+bob,6,5);
      GC.fillStyle='#aa7744'; GC.fillRect(sx+4,sy+2+bob,8,4);
      GC.fillStyle='#8888bb'; GC.fillRect(sx+4,sy+9+bob,8,7);
      GC.fillStyle='#000'; GC.fillRect(sx+6,sy+5+bob,2,2); GC.fillRect(sx+9,sy+5+bob,2,2);
      // drawing paper
      GC.fillStyle=C.WHT; GC.fillRect(sx+12,sy+9+bob,5,6);
      GC.fillStyle='#cc0000'; GC.fillRect(sx+13,sy+10+bob,3,4);
      break;
    case 'ghost':
      GC.globalAlpha=0.7+Math.sin(S.fc*0.08)*0.15;
      GC.fillStyle='#aaccff'; GC.fillRect(sx+4,sy+2+bob,8,6);
      GC.fillStyle='#8899cc'; GC.fillRect(sx+3,sy+8+bob,10,7);
      GC.fillStyle='#000020'; GC.fillRect(sx+6,sy+4+bob,2,2); GC.fillRect(sx+9,sy+4+bob,2,2);
      GC.fillStyle='#aaccff';
      GC.fillRect(sx+3,sy+14+bob,3,3); GC.fillRect(sx+7,sy+15+bob,2,3); GC.fillRect(sx+11,sy+14+bob,3,3);
      GC.globalAlpha=1;
      break;
    case 'wanderer':
      GC.fillStyle=C.BRN; GC.fillRect(sx+3,sy+7+bob,10,9);
      GC.fillStyle='#c09060'; GC.fillRect(sx+4,sy+2+bob,8,6);
      GC.fillStyle='#664422'; GC.fillRect(sx+3,sy+1+bob,10,4);
      GC.fillStyle='#442211'; GC.fillRect(sx+4,sy+6+bob,8,3);
      GC.fillStyle='#000'; GC.fillRect(sx+5,sy+3+bob,2,2); GC.fillRect(sx+9,sy+3+bob,2,2);
      break;
  }
  // Talk prompt
  const dist=Math.hypot(S.player.x-npc.x,S.player.y-npc.y);
  if(dist<npc.talkDist+2){
    const pulse=Math.floor(S.fc/20)%2;
    if(pulse){ GC.fillStyle=C.YLW; GC.fillRect(sx+5,sy-8,8,6); GC.fillStyle='#000'; GC.fillRect(sx+7,sy-7,4,3); GC.fillRect(sx+7,sy-5,1,1); }
  }
}
