const W=256;

const H=224;

const S={
  scene:SC.TITLE, prevScene:SC.GAME,
  phase:PH.DAY, phaseT:0,
  phaseDur:[2400,180,1800,120], // frames per phase (40fps equiv)
  day:1,

  player:{
    x:240,y:192, vx:0,vy:0, spd:1.6,
    hp:6,maxHp:6,
    oil:100,maxOil:100,
    curse:0,maxCurse:100,
    weapon:0, // 0=shovel 1=hook 2=axe 3=hammer
    facing:2, // 0=up 1=right 2=down 3=left
    atkT:0,atkDur:16,
    inv:0, knockX:0,knockY:0,
    lantern:true,
    walkF:0,walkT:0,
    dead:false,
  },

  maps:{},curMap:'chapel',
  cam:{x:0,y:0},
  enemies:[],particles:[],
  npcs:[],bells:[],items:[],signs:[],

  dlg:{active:false,lines:[],idx:0,spk:'',cb:null},
  flags:{},lore:[],

  // Bell system
  bellHealth:{chapel:3,graveyard:3,village:3},

  fx:0,shakeX:0,shakeY:0,shakeDur:0,
  fc:0, // frame counter

  // Transition
  transAlpha:0,transDir:1,transCb:null,

  // Boss
  boss:null,

  titleF:0,
  introIdx:0,introT:0,introAlpha:0,introFade:false,

  ending:-1,

  // Location banner
  banner:'',bannerT:0,

  // Night warning flash
  nightWarn:0,
};

const PH={DAY:0,DUSK:1,NIGHT:2,DAWN:3};

const HH=16;

const TW=16;

function getT(m,w,mh,x,y){ if(x<0||y<0||x>=w||y>=mh) return T.WALL; return m[y*w+x]; }

const T={
  FLOOR:0,WALL:1,BRICK:2,DOOR:3,ALTAR:4,GRAVE:5,TREE:6,
  WATER:7,BELL:9,PILLAR:10,TORCH:11,STAIR_D:12,STAIR_U:13,
  RUBBLE:14,FENCE:15,CRACK:16,CHEST:17,SIGN:18,WELL:19,FORGE:20,
};

const SC={TITLE:0,INTRO:1,GAME:2,DIALOG:3,PAUSE:4,TRANSITION:5,GAMEOVER:6,BOSS:7,ENDING:8};

function renderLight(cx,cy){
  LC.clearRect(0,0,W,H);
  const p=S.player;
  let dark=0;
  if(S.phase===PH.NIGHT) dark=0.93;
  else if(S.phase===PH.DUSK) dark=0.5;
  else if(S.phase===PH.DAWN) dark=0.3;
  dark=Math.min(0.97,dark+(p.curse/p.maxCurse)*0.25);
  if(dark<=0) return;
  LC.fillStyle=`rgba(0,0,0,${dark})`;
  LC.fillRect(0,0,W,H);
  if(p.lantern&&p.oil>0){
    const lx=(p.x-cx)|0, ly=(p.y-cy)|0+HH+8;
    const radius=Math.max(20,(p.oil/p.maxOil)*85);
    LC.save();
    LC.globalCompositeOperation='destination-out';
    const gr=LC.createRadialGradient(lx,ly,0,lx,ly,radius);
    gr.addColorStop(0,'rgba(0,0,0,1)');
    gr.addColorStop(0.55,'rgba(0,0,0,0.9)');
    gr.addColorStop(0.82,'rgba(0,0,0,0.4)');
    gr.addColorStop(1,'rgba(0,0,0,0)');
    LC.fillStyle=gr;
    LC.beginPath(); LC.arc(lx,ly,radius,0,Math.PI*2); LC.fill();
    LC.restore();
    // warm tint
    LC.save();
    LC.globalCompositeOperation='source-over';
    const warm=LC.createRadialGradient(lx,ly,0,lx,ly,radius*0.65);
    warm.addColorStop(0,'rgba(200,80,0,0.07)');
    warm.addColorStop(1,'rgba(0,0,0,0)');
    LC.fillStyle=warm; LC.beginPath(); LC.arc(lx,ly,radius*0.65,0,Math.PI*2); LC.fill();
    LC.restore();
  }
  // Torch lights in current map
  const map=S.maps[S.curMap]; if(!map) return;
  const stx=Math.floor(cx/TW),sty=Math.floor(cy/TW);
  for(let r=sty-1;r<sty+15;r++) for(let c=stx-1;c<stx+18;c++){
    if(getT(map.data,map.w,map.h,c,r)===T.TORCH){
      const tx=(c*TW+8-cx)|0, ty=(r*TW+4-cy)|0+HH;
      LC.save();
      LC.globalCompositeOperation='destination-out';
      const tg=LC.createRadialGradient(tx,ty,0,tx,ty,28);
      tg.addColorStop(0,'rgba(0,0,0,0.75)');
      tg.addColorStop(1,'rgba(0,0,0,0)');
      LC.fillStyle=tg; LC.beginPath(); LC.arc(tx,ty,28,0,Math.PI*2); LC.fill();
      LC.restore();
    }
  }
}
