const PH={DAY:0,DUSK:1,NIGHT:2,DAWN:3};

const TW=16;

function playBellDie(){
  [523,494,466,440,415,392].forEach((f,i)=>note(f,0.3,'sine',0.2,i*0.15));
}

function spawnParts(x,y,type,n=6){
  for(let i=0;i<n;i++){
    const a=Math.PI*2*i/n+Math.random();
    const spd=0.6+Math.random()*1.8;
    let col;
    if(type==='blood') col=[C.BLOOD,C.MIDRED,'#440000'][i%3];
    else if(type==='holy') col=[C.GOLD,C.YLW,C.WHT][i%3];
    else if(type==='curse') col=[C.PURP,'#6600aa','#330066'][i%3];
    else if(type==='smoke') col=['#444444','#333333','#222222'][i%3];
    else col=C.LTGRY;
    S.particles.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,
      life:15+Math.random()*25,maxLife:40,col,sz:(1+Math.random()*2)|0});
  }
}

function startDlg(lines,cb){
  S.scene=SC.DIALOG;
  S.dlg={active:true,lines,idx:0,spk:lines[0][0],cb:cb||null};
}

function playCurse(){ note(55,0.5,'sawtooth',0.08); note(73,0.4,'sawtooth',0.06,0.1); }

function playBell(){
  const freqs=[523,659,523];
  freqs.forEach((f,i)=>{note(f,0.8,'sine',0.25,i*0.3); note(f*2,0.4,'sine',0.08,i*0.3+0.05);});
}

const SC={TITLE:0,INTRO:1,GAME:2,DIALOG:3,PAUSE:4,TRANSITION:5,GAMEOVER:6,BOSS:7,ENDING:8};

function note(freq,dur,type='square',vol=0.15,delay=0){
  if(!ACtx) return;
  const o=ACtx.createOscillator();
  const g=ACtx.createGain();
  const now=ACtx.currentTime+delay;
  o.connect(g); g.connect(ACtx.destination);
  o.type=type; o.frequency.setValueAtTime(freq,now);
  g.gain.setValueAtTime(0,now);
  g.gain.linearRampToValueAtTime(vol,now+0.01);
  g.gain.exponentialRampToValueAtTime(0.001,now+dur);
  o.start(now); o.stop(now+dur+0.05);
}

const C={
  BLK:'#000000', NAVY:'#08103a', DKBLU:'#0b0d2e', MIDBLU:'#2844c8',
  BLOOD:'#7a0000', DKRED:'#3d0000', MIDRED:'#b01010', RUST:'#6b3000',
  BRN:'#5c2a00', DKGRN:'#003d00', MIDGRN:'#006b00', SICKGRN:'#4a6b00',
  DKGRY:'#1a1a1a', MIDGRY:'#3a3a3a', LTGRY:'#7a7a7a', SILV:'#bcbcbc',
  WHT:'#f8f8f8', YLW:'#d8b000', GOLD:'#b88000', PURP:'#2d004a',
  DKPUR:'#180028', FLAME:'#e05000', AMBRE:'#d87800', TAN:'#c09860',
  SKIN:'#d89060', BONE:'#c8b078', FOGBLU:'#182858', TEAL:'#006868',
};

let ACtx=null;

function tickBells(){
  if(S.phase!==PH.NIGHT) return;
  const map=S.maps[S.curMap]; if(!map||!map.bellPos) return;
  // every 300 frames at night, damage the bell
  if(S.fc%300===0&&S.bellHealth[S.curMap]>0){
    const p=S.player;
    const bx=map.bellPos.x*TW, by=map.bellPos.y*TW;
    const dist=Math.hypot(p.x-bx,p.y-by);
    if(dist>80){
      // Player not defending — bell takes damage
      S.bellHealth[S.curMap]--;
      playBellDie();
      spawnParts(bx,by,'curse',8);
      S.nightWarn=180;
      if(S.bellHealth[S.curMap]<=0){
        startDlg([['','A bell has gone silent. The curse spreads deeper.']],()=>{});
        S.player.curse=Math.min(S.player.maxCurse,S.player.curse+20);
        playCurse();
      }
    } else {
      // Player is near bell — it rings
      playBell();
      spawnParts(bx,by,'holy',6);
    }
  }
  // Wraiths drawn to bell
  if(S.fc%120===0){
    for(const e of S.enemies){
      if(e.type==='bell_wraith'&&map.bellPos){
        // pull toward bell
        e.targetBell=true;
      }
    }
  }
}
