function moveWithCollision(obj,dx,dy){
  const nx=obj.x+dx,ny=obj.y+dy;
  const px1=3,px2=13,py1=8,py2=15;
  let mx=true,my=true;
  if(isSolid(nx+px1,obj.y+py1)||isSolid(nx+px2,obj.y+py1)||
     isSolid(nx+px1,obj.y+py2)||isSolid(nx+px2,obj.y+py2)) mx=false;
  if(isSolid(obj.x+px1,ny+py1)||isSolid(obj.x+px2,ny+py1)||
     isSolid(obj.x+px1,ny+py2)||isSolid(obj.x+px2,ny+py2)) my=false;
  if(mx) obj.x=nx;
  if(my) obj.y=ny;
}

const TW=16;

