function damagePlayer(dmg,ex,ey){
  const p=S.player;
  if(p.inv>0) return;
  p.hp=Math.max(0,p.hp-dmg);
  p.inv=80;
  p.curse=Math.min(p.maxCurse,p.curse+6);
  // knockback away from enemy
  if(ex!==undefined){
    const dx=p.x-ex, dy=p.y-ey;
    const d=Math.hypot(dx,dy)||1;
    p.knockX=dx/d*4; p.knockY=dy/d*4;
  }
  shake(7); playHit();
  if(p.hp<=0) S.scene=SC.GAMEOVER;
}

const SC={TITLE:0,INTRO:1,GAME:2,DIALOG:3,PAUSE:4,TRANSITION:5,GAMEOVER:6,BOSS:7,ENDING:8};

function isSolid(x,y){
  const map=S.maps[S.curMap]; if(!map) return true;
  const tx=Math.floor(x/TW), ty=Math.floor(y/TW);
  const t=getT(map.data,map.w,map.h,tx,ty);
  return SOLID_TILES.has(t);
}

function shake(intensity){
  S.shakeDur=Math.max(S.shakeDur,intensity*3);
}

function playHit(){   note(220,0.05,'square',0.2); note(110,0.08,'sawtooth',0.1,0.03); }

function getT(m,w,mh,x,y){ if(x<0||y<0||x>=w||y>=mh) return T.WALL; return m[y*w+x]; }

const SOLID_TILES=new Set([T.WALL,T.BRICK,T.TREE,T.PILLAR,T.FENCE,T.STAIR_D,T.FORGE]);

function note(freq,dur,type='square',vol=0.15,delay=0){
  if(!ACtx) return;
  const o=ACtx.createOscillator();
  const g=ACtx.createGain();
  const now=ACtx.currentTime+delay;
  o.connect(g); g.connect(ACtx.destination);
  o.type=type; o.frequency.setValueAtTime(freq,now);
  g.gain.setValueAtTime(0,now);
  g.gain.linearRampToValueAtTime(vol,now+0.01);
  g.gain.exponentialRampToValueAtTime(0.001,now+dur);
  o.start(now); o.stop(now+dur+0.05);
}

const T={
  FLOOR:0,WALL:1,BRICK:2,DOOR:3,ALTAR:4,GRAVE:5,TREE:6,
  WATER:7,BELL:9,PILLAR:10,TORCH:11,STAIR_D:12,STAIR_U:13,
  RUBBLE:14,FENCE:15,CRACK:16,CHEST:17,SIGN:18,WELL:19,FORGE:20,
};

let ACtx=null;

function tickEnemies(){
  const p=S.player;
  const map=S.maps[S.curMap]; if(!map) return;
  for(let i=S.enemies.length-1;i>=0;i--){
    const e=S.enemies[i];
    if(e.dead){S.enemies.splice(i,1);continue;}
    if(e.hitF>0) e.hitF--;
    if(e.atkT>0) e.atkT--;

    // knockback decay
    if(e.knockX||e.knockY){
      moveWithCollision(e,e.knockX,e.knockY);
      e.knockX*=0.7; e.knockY*=0.7;
      if(Math.abs(e.knockX)<0.1) e.knockX=0;
      if(Math.abs(e.knockY)<0.1) e.knockY=0;
      continue;
    }

    const bpos=map.bellPos;
    let tx=p.x,ty=p.y;
    // Bell wraith targets bell if player far
    if(e.type==='bell_wraith'&&bpos){
      const distP=Math.hypot(p.x-e.x,p.y-e.y);
      const distB=Math.hypot(bpos.x*TW-e.x,bpos.y*TW-e.y);
      if(distP>100&&distB<distP){tx=bpos.x*TW;ty=bpos.y*TW;}
    }

    const dx=tx-e.x, dy=ty-e.y;
    const dist=Math.hypot(dx,dy);
    const nightBoost=S.phase===PH.NIGHT?1.3:0.45;

    if(dist<e.detR){
      if(dist>e.aRange){
        const spd=e.spd*nightBoost;
        const mx=(dx/dist)*spd+(e.vx*0.6);
        const my=(dy/dist)*spd+(e.vy*0.6);
        const ms=Math.hypot(mx,my);
        e.vx=ms>spd?mx/ms*spd:mx;
        e.vy=ms>spd?my/ms*spd:my;
        moveWithCollision(e,e.vx,e.vy);
      } else {
        if(e.atkT<=0){
          damagePlayer(e.atk,dx,dy);
          e.atkT=e.acd;
        }
      }
    } else {
      e.vx*=0.85; e.vy*=0.85;
    }
  }
}
