}

function playDie(){   [220,180,140,100].forEach((f,i)=>note(f,0.12,'square',0.18,i*0.06)); }

function playBell(){
  const freqs=[523,659,523];
  freqs.forEach((f,i)=>{note(f,0.8,'sine',0.25,i*0.3); note(f*2,0.4,'sine',0.08,i*0.3+0.05);});
