function shake(intensity){
  S.shakeDur=Math.max(S.shakeDur,intensity*3);
}

function playHit(){   note(220,0.05,'square',0.2); note(110,0.08,'sawtooth',0.1,0.03); }

function spawnParts(x,y,type,n=6){
  for(let i=0;i<n;i++){
    const a=Math.PI*2*i/n+Math.random();
    const spd=0.6+Math.random()*1.8;
    let col;
    if(type==='blood') col=[C.BLOOD,C.MIDRED,'#440000'][i%3];
    else if(type==='holy') col=[C.GOLD,C.YLW,C.WHT][i%3];
    else if(type==='curse') col=[C.PURP,'#6600aa','#330066'][i%3];
    else if(type==='smoke') col=['#444444','#333333','#222222'][i%3];
    else col=C.LTGRY;
    S.particles.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,
      life:15+Math.random()*25,maxLife:40,col,sz:(1+Math.random()*2)|0});
  }
}

function playBell(){
  const freqs=[523,659,523];
  freqs.forEach((f,i)=>{note(f,0.8,'sine',0.25,i*0.3); note(f*2,0.4,'sine',0.08,i*0.3+0.05);});
}

