function note(freq,dur,type='square',vol=0.15,delay=0){
  if(!ACtx) return;
  const o=ACtx.createOscillator();
  const g=ACtx.createGain();
  const now=ACtx.currentTime+delay;
  o.connect(g); g.connect(ACtx.destination);
  o.type=type; o.frequency.setValueAtTime(freq,now);
  g.gain.setValueAtTime(0,now);
  g.gain.linearRampToValueAtTime(vol,now+0.01);
  g.gain.exponentialRampToValueAtTime(0.001,now+dur);
  o.start(now); o.stop(now+dur+0.05);
}

const C={
  BLK:'#000000', NAVY:'#08103a', DKBLU:'#0b0d2e', MIDBLU:'#2844c8',
  BLOOD:'#7a0000', DKRED:'#3d0000', MIDRED:'#b01010', RUST:'#6b3000',
  BRN:'#5c2a00', DKGRN:'#003d00', MIDGRN:'#006b00', SICKGRN:'#4a6b00',
  DKGRY:'#1a1a1a', MIDGRY:'#3a3a3a', LTGRY:'#7a7a7a', SILV:'#bcbcbc',
  WHT:'#f8f8f8', YLW:'#d8b000', GOLD:'#b88000', PURP:'#2d004a',
  DKPUR:'#180028', FLAME:'#e05000', AMBRE:'#d87800', TAN:'#c09860',
  SKIN:'#d89060', BONE:'#c8b078', FOGBLU:'#182858', TEAL:'#006868',
};

function doTransition(cb){
  if(S.scene===SC.TRANSITION) return;
  S.prevScene=S.scene;
  S.scene=SC.TRANSITION;
  S.transAlpha=0; S.transDir=1; S.transCb=cb;
}

let ACtx=null;

function bossTakeDamage(ax,ay,aw,ah){
  const b=S.boss; if(!b||b.hitF>0) return;
  // hit hands
  for(const h of b.hands){
    if(ax<h.x+24&&ax+aw>h.x&&ay<h.y+24&&ay+ah>h.y){
      b.hp--; b.hitF=15; shake(8); playHit(); spawnParts(h.x+12,h.y+12,'blood',6);
      break;
    }
  }
  // hit main body
  if(ax<b.x+32&&ax+aw>b.x&&ay<b.y+32&&ay+ah>b.y){
    if(b.phase>=1){ b.hp-=2; b.hitF=15; shake(10); playHit(); spawnParts(b.x+16,b.y+16,'blood',8); }
  }
  if(b.hitF>0){
    if(b.hp<=20&&b.phase<1){ b.phase=1; playBell(); spawnParts(W/2,H/2,'curse',12); }
    if(b.hp<=10&&b.phase<2){ b.phase=2; playBell(); spawnParts(W/2,H/2,'curse',16); }
    if(b.hp<=0){ endBoss(); }
  }
}
