  ptext(UC,'HOLLOW KING',bx2+2,H-14,'#ff4444');

  // Phase name
  const pnames=['I - HANDS','II - SKULL','III - RISEN'];
  ptext(UC,'PHASE '+pnames[b.phase],(W-ptw('PHASE '+pnames[b.phase]))/2|0,H-24,C.AMBRE);
}
