function ptext(ctx,str,x,y,col,sc=1){
  ctx.fillStyle=col;
  let cx=x;
  for(const ch of str.toUpperCase()){
    const g=FONT[ch];
    if(!g){cx+=4*sc;continue;}
    for(let r=0;r<5;r++) for(let c=0;c<3;c++)
      if(g[r][c]) ctx.fillRect(cx+c*sc,y+r*sc,sc,sc);
    cx+=4*sc;
  }
}

function ptw(str){ return str.length*4; }

