const SC={TITLE:0,INTRO:1,GAME:2,DIALOG:3,PAUSE:4,TRANSITION:5,GAMEOVER:6,BOSS:7,ENDING:8};

function loadMap(mapId,px,py){
  if(!S.maps[mapId]) return;
  S.curMap=mapId;
  S.player.x=px; S.player.y=py;
  S.enemies=[];
  if(S.phase===PH.NIGHT) spawnNightEnemies();
  const mdef=S.maps[mapId];
  S.npcs=mdef.npcs?mdef.npcs.map(n=>({...n})):[];
  S.bells=mdef.bellPos?[mdef.bellPos]:[];
  // set music
  curMusicKey=S.phase===PH.NIGHT?'night':(mdef.musicKey||'chapel');
  musicSeq=0; musicRow=0;
  // show location banner
  S.banner=mdef.name||'';
  S.bannerT=120;
  // update camera
  const map=mdef;
  const maxCX=Math.max(0,map.w*TW-W);
  const maxCY=Math.max(0,map.h*TW-(H-HH));
  S.cam.x=Math.max(0,Math.min(maxCX,(px-W/2)|0));
  S.cam.y=Math.max(0,Math.min(maxCY,(py-(H-HH)/2)|0));
}

let curMusicKey='chapel';

let musicSeq=0;

let musicRow=0;

function spawnNightEnemies(){
  const map=S.maps[S.curMap]; if(!map) return;
  S.enemies=[];
  const count=Math.min(8,2+S.day);
  const pool=['gravewalker'];
  if(S.day>=2) pool.push('husk_dog');
  if(S.day>=3) pool.push('bell_wraith');
  for(let i=0;i<count;i++){
    let ex,ey,tries=0;
    do{
      ex=(1+Math.floor(Math.random()*(map.w-2)))*TW;
      ey=(1+Math.floor(Math.random()*(map.h-2)))*TW;
      tries++;
    }while(tries<30&&isSolid(ex+8,ey+8));
    spawnEnemy(pool[Math.floor(Math.random()*pool.length)],ex,ey);
  }
}

const W=256;

const H=224;

const HH=16;

function isSolid(x,y){
  const map=S.maps[S.curMap]; if(!map) return true;
  const tx=Math.floor(x/TW), ty=Math.floor(y/TW);
  const t=getT(map.data,map.w,map.h,tx,ty);
  return SOLID_TILES.has(t);
}

function spawnEnemy(type,x,y){
  const cfg={
    gravewalker:{hp:3,spd:0.45,atk:1,acd:60,aRange:12,detR:90},
    bell_wraith: {hp:5,spd:0.75,atk:2,acd:80,aRange:14,detR:110,telCd:0},
    husk_dog:    {hp:2,spd:1.15,atk:1,acd:38,aRange:10,detR:85},
  };
  const c=cfg[type]||cfg.gravewalker;
  S.enemies.push({...c,type,x,y,vx:0,vy:0,atkT:0,hitF:0,dead:false,
    knockX:0,knockY:0,targetBell:false});
}

function getT(m,w,mh,x,y){ if(x<0||y<0||x>=w||y>=mh) return T.WALL; return m[y*w+x]; }

const SOLID_TILES=new Set([T.WALL,T.BRICK,T.TREE,T.PILLAR,T.FENCE,T.STAIR_D,T.FORGE]);

const T={
  FLOOR:0,WALL:1,BRICK:2,DOOR:3,ALTAR:4,GRAVE:5,TREE:6,
  WATER:7,BELL:9,PILLAR:10,TORCH:11,STAIR_D:12,STAIR_U:13,
