const ZONE_PAL = {
  [ZONE_ID.ENTRY]: {
    /* Entry Hall — NES Castlevania Stage 1 orange-brown brick.
       Uses $07/$17/$27/$37 brown column from the 2C02 palette.
       Mortar is near-black $01. Exactly the warm castle wall look. */
    bg:          '#000000',   /* $0F black sky behind windows          */
    solidBase:   '#503000',   /* $17 — mid brick body                  */
