const PAL = Object.freeze({
  /* ── True NES 2C02 hardware colours ──────────────────────────
     Every value is taken directly from the NES system palette.
     Castlevania (1986) used at most 4 colours per tile/sprite.
     Source: NesDev wiki 2C02 palette, Castlevania ROM analysis. */

  /* Neutral / backgrounds */
  BLACK:      '#000000',   /* $0F — universal black                  */
  DARKGRAY:   '#2c2c2c',   /* $00 — NES dark grey                    */
  MIDGRAY:    '#6c6c6c',   /* $10 — medium grey                      */
