  FPS:      60,
  FRAME_MS: 1000 / 60,
});

function tileIsSolid(id)  { return TILE_PROPS[id] ? TILE_PROPS[id].solid  : false; }

function tileAt(mapData, tx, ty) {
  if (tx < 0 || ty < 0 || tx >= mapData.cols || ty >= mapData.rows) return T.SOLID;
  return mapData.data[ty * mapData.cols + tx];
}

function aabbOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}

function enemyTakeDamage(enemy, amount, sourceX) {
  if (enemy.state === 'hurt' || enemy.state === 'dead') return;
  enemy.hp = Math.max(0, enemy.hp - amount);
  enemy.state    = 'hurt';
  enemy.stateTimer = 0;
  enemy.hurtTimer  = 20;
  const dir  = (enemy.x + enemy.w * 0.5) > sourceX ? 1 : -1;
  enemy.vx   = dir * 2.5;
  enemy.vy   = enemy.type === 'bat' ? -1.5 : -2.0;
}

const STATE = Object.freeze({
  TITLE:    'TITLE',
  INTRO:    'INTRO',    /* opening crawl + walking animation */
  PLAYING:  'PLAYING',
  LORE_READ:'LORE_READ',/* freeze everything — player reading a lore fragment */
  PAUSED:   'PAUSED',
  DEAD:     'DEAD',
  WIN:      'WIN',
});

const TILE_PROPS = (function() {
  const p = [];
  const def = (id, solid, oneway, hazard, trigger) =>
    (p[id] = { solid, oneway, hazard, trigger: trigger || null });
  def(T.AIR,      false, false, false);
  def(T.SOLID,    true,  false, false);
  def(T.PLATFORM, false, true,  false);
  def(T.SPIKE,    false, false, true);
  def(T.LORE,     false, false, false, 'lore');
  def(T.WEAPON,   false, false, false, 'weapon');
  def(T.DOOR_UP,  false, false, false, 'door_up');
  def(T.DOOR_L,   false, false, false, 'door_l');
  def(T.DOOR_R,   false, false, false, 'door_r');
  def(T.DOOR_D,   false, false, false, 'door_d');
  return p;
})();

const T = Object.freeze({
  AIR: 0, SOLID: 1, PLATFORM: 2, SPIKE: 3,
  LORE: 5, WEAPON: 6, DOOR_UP: 7, DOOR_L: 8, DOOR_R: 9, DOOR_D: 10,
});

function updateProjectiles() {
  const zone = G.currentZoneId ? ZONES[G.currentZoneId] : null;
  const md   = zone ? zone.mapData : null;
  const p    = G.player;

  for (let i = projectiles.length - 1; i >= 0; i--) {
    const pr = projectiles[i];
    pr.life--;
    pr.x += pr.vx;
    pr.y += pr.vy;

    if (pr.type === 'axe') {
      pr.vy    += 0.22;   /* gravity on axe */
      pr.rotation = (pr.rotation || 0) + (pr.vx > 0 ? 0.2 : -0.2);
    }

    /* Remove if expired or hits solid tile */
    if (pr.life <= 0) { projectiles.splice(i, 1); continue; }
    if (md) {
      const tx = (pr.x / NES.TILE) | 0;
      const ty = (pr.y / NES.TILE) | 0;
      if (tileIsSolid(tileAt(md, tx, ty))) {
        projectiles.splice(i, 1); continue;
      }
    }

    /* Hit enemies */
    if (zone && zone.enemies) {
      for (const e of zone.enemies) {
        if (e.dead || e.state === 'hurt') continue;
        if (e.lastHitSwing === pr.swingId) continue;
        if (aabbOverlap(pr, e)) {
          e.lastHitSwing = pr.swingId;
          enemyTakeDamage(e, pr.damage, pr.x);
          projectiles.splice(i, 1); break;
        }
      }
    }

    /* Projectiles also hit The Hand */
    if (G.theHand && G.theHand.active && !G.theHand.stunTimer) {
      if (aabbOverlap(pr, G.theHand)) {
        G.theHand.stun();
        projectiles.splice(i, 1); continue;
      }
    }
  }
}
