  /* Zone 3 enemies */
  mech_construct: {
    w: 14, h: 20, hp: 3,
    speed: 0.55, aggroRange: 88,
    gravity: true, contactDamage: 1,
    shootRange: 80,  /* fires projectile when player in range */
    shootCooldown: 90,
  },
  clockwork_bird: {
    w: 12, h: 10, hp: 1,
