function updateEnemyClockworkBird(enemy, player) {
  /* Reuse bat AI with slightly different params */
  const cfg = ENEMY_CFG_ALL.clockwork_bird;
  if (enemy.state === 'dead') { if (++enemy.stateTimer >= 30) enemy.dead = true; return; }
