    enemy.vx *= 0.8; enemy.vy *= 0.85;
    if (enemy.stateTimer >= 12) {
      enemy.state = enemy.hp <= 0 ? 'dead' : 'returning'; enemy.stateTimer = 0;
    }
    return;
