  ctx.restore();
  ctx.fillStyle = C2;
  ctx.fillRect(4, 4, 6, 6);    /* gear center */
  ctx.fillStyle = C3;
  ctx.fillRect(5, 5, 4, 4);    /* core glint */

  /* Heavy body */
  ctx.fillStyle = C1;
  ctx.fillRect(0, 13, 14, 8);
  ctx.fillStyle = C2;
  ctx.fillRect(2, 14, 10, 5);
