    speed: 0.7, aggroRange: 112,
    gravity: false, contactDamage: 1,
    phaseTimer: 0,   /* ghosts phase through walls */
  },
  /* Zone 3 enemies */
  mech_construct: {
    w: 14, h: 20, hp: 3,
    speed: 0.55, aggroRange: 88,
    gravity: true, contactDamage: 1,
    shootRange: 80,  /* fires projectile when player in range */
    shootCooldown: 90,
