  /* Inner highlight — 1px inset from border */
  ctx.fillStyle = hi;
  ctx.fillRect(x+2,       y+2,       w-4,  1); /* top hi    */
  ctx.fillRect(x+2,       y+2,       1,  h-4); /* left hi   */

