    [[x, y], [x+w-4, y], [x, y+h-4], [x+w-4, y+h-4]].forEach(([cx, cy]) => {
      ctx.fillStyle = C;
      ctx.fillRect(cx+1, cy,   2, 4);
      ctx.fillRect(cx,   cy+1, 4, 2);
    });
