function drawCastleSilhouette(ctx) {
  ctx.fillStyle = PAL.STONE_DARK;

  /* Base ramparts */
  ctx.fillRect(0, 160, 256, 64);

  /* Tower left */
  ctx.fillRect(10, 110, 30, 50);
  ctx.fillRect(8,  105, 6, 6);    /* battlement */
  ctx.fillRect(18, 105, 6, 6);
  ctx.fillRect(28, 105, 6, 6);

