  ctx.fillRect(60, 120, 40, 40);
  ctx.fillRect(58, 114, 8, 8);
  ctx.fillRect(72, 114, 8, 8);
  ctx.fillRect(86, 114, 8, 8);

  /* Main keep */
  ctx.fillRect(108, 95, 48, 65);
  ctx.fillRect(106, 87, 10, 10);
  ctx.fillRect(122, 87, 10, 10);
  ctx.fillRect(138, 87, 10, 10);

