  ctx.fillStyle = PAL.LIGHTGRAY;
  ctx.beginPath();
  ctx.arc(210, 50, 18, 0, Math.PI * 2);
  ctx.fill();

  /* Moon shadow (crescent) */
  ctx.fillStyle = PAL.STONE_DARK;
  ctx.beginPath();
  ctx.arc(218, 46, 16, 0, Math.PI * 2);
  ctx.fill();

