  const spawnX = (zone.spawnTX != null ? zone.spawnTX : 3) * NES.TILE;
  const spawnY = (zone.spawnTY != null ? zone.spawnTY : 10) * NES.TILE - PHYS.PLAYER_H;

  Camera.reset();   /* always reset — prevents camera snap on respawn */

  G.player = {
    /* Position + velocity (hitbox top-left) */
    x: spawnX, y: spawnY,
    w: PHYS.PLAYER_W, h: PHYS.PLAYER_H,
    vx: 0, vy: 0,

    /* State flags */
    onGround:  false,
    facing:    1,         /* 1=right  -1=left */

    /* Combat */
    hp:        6,
    maxHp:     6,
    iFrames:   0,         /* invincibility frames remaining */
    kbTimer:   0,         /* knockback frames remaining */
    attackTimer: 0,       /* attack animation frames remaining */

    /* Animation */
    animFrame: 0,
    animTimer: 0,

    /* Inventory — Sections 3-6 add weapons */
    weapons:    ['sword'],
    weaponIdx:  0,

    /* Notification text for pickups */
    notifyText: '',
    notifyTimer: 0,
  };
  if (DEBUG) console.log(`[player] spawned at (${spawnX}, ${spawnY})`);
}

const pauseScreen = {
  cursor: 0,   /* 0=RESUME 1=TITLE */
  options: ['RESUME', 'QUIT TO TITLE'],

  update() {
    if (INPUT.START.just || INPUT.A.just) {
      if (this.cursor === 0) setState(STATE.PLAYING);
      else                   setState(STATE.TITLE);
    }
    if (INPUT.DOWN.just) this.cursor = (this.cursor + 1) % this.options.length;
    if (INPUT.UP.just)   this.cursor = (this.cursor - 1 + this.options.length) % this.options.length;
  },

  draw(ctx) {
    /* Darken the background */
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, NES.W, NES.H);

    /* Panel */
    ctx.fillStyle = PAL.STONE_MID;
    ctx.fillRect(72, 80, 112, 64);
    ctx.fillStyle = PAL.STONE_HIGH;
    ctx.fillRect(72, 80, 112, 1);
    ctx.fillRect(72, 143, 112, 1);
    ctx.fillRect(72, 80, 1, 64);
    ctx.fillRect(183, 80, 1, 64);

    ctx.fillStyle = PAL.PALE_GOLD;
    ctx.font = '8px monospace';
    ctx.textAlign = 'center';
    ctx.fillText('- PAUSED -', NES.W / 2, 96);

    this.options.forEach((opt, i) => {
      ctx.fillStyle = (i === this.cursor) ? PAL.CURSOR : PAL.HUD_TEXT;
      ctx.fillText(opt, NES.W / 2, 116 + i * 14);
      if (i === this.cursor) {
        ctx.fillText('>', 82, 116 + i * 14);
      }
    });
    ctx.textAlign = 'left';
  },
};

const deadScreen = {
  timer: 0,

  update() {
    this.timer++;
    if (this.timer > 180 && (INPUT.START.just || INPUT.A.just)) {
      this.timer = 0;
      G.player       = null;   /* re-init on PLAYING enter */
      G.currentZoneId = null;  /* always respawn in ENTRY, not the zone of death */
      setState(STATE.PLAYING);
    }
  },

  draw(ctx) {
    ctx.fillStyle = PAL.BLACK;
    ctx.fillRect(0, 0, NES.W, NES.H);

    ctx.fillStyle = PAL.BLOOD_RED;
    ctx.font = '16px monospace';
    ctx.textAlign = 'center';
