const ZONES = {};

const Camera = {
  x: 0, y: 0, targetX: 0, targetY: 0,

  follow(entity) {
    const zone = G.currentZoneId ? ZONES[G.currentZoneId] : null;
    const mapW = zone && zone.mapData ? zone.mapData.cols * NES.TILE : NES.W;
    const mapH = zone && zone.mapData ? zone.mapData.rows * NES.TILE : NES.H;
    const maxX = Math.max(0, mapW - NES.W);
    const maxY = Math.max(0, mapH - NES.H);
    const cx = entity ? entity.x - NES.W / 2 + (entity.w >> 1) : this.targetX;
    const cy = entity ? entity.y - NES.H / 2 + (entity.h >> 1) : this.targetY;
    this.targetX = Math.max(0, Math.min(cx, maxX));
    this.targetY = Math.max(0, Math.min(cy, maxY));
    this.x = Math.round(this.targetX);
    this.y = Math.round(this.targetY);
  },

  pan(dx, dy) {
    const zone = G.currentZoneId ? ZONES[G.currentZoneId] : null;
    const mapW = zone && zone.mapData ? zone.mapData.cols * NES.TILE : NES.W;
    const mapH = zone && zone.mapData ? zone.mapData.rows * NES.TILE : NES.H;
    const maxX = Math.max(0, mapW - NES.W);
    const maxY = Math.max(0, mapH - NES.H);
    this.x = Math.max(0, Math.min(this.x + dx, maxX));
    this.y = Math.max(0, Math.min(this.y + dy, maxY));
    this.targetX = this.x; this.targetY = this.y;
  },

  reset() { this.x = this.y = this.targetX = this.targetY = 0; },
};

const DEBUG = true;

const PHYS = Object.freeze({
  GRAVITY:      0.35,
  MAX_FALL:     8,
  WALK:         1.5,
  JUMP:         -6.5,    /* 60px max height: row-7(48px)✓ row-5 via row-7(32px)✓ */
  KB_X:         3.5,
  KB_Y:         -3.0,
  KB_FRAMES:    20,
  IFRAME_DUR:   60,
  ATTACK_DUR:   18,
  PLAYER_W:     14,
  PLAYER_H:     22,
});

function onStateEnter(s) {
  switch (s) {
    case STATE.TITLE:
      titleScreen.reset();
      break;
    case STATE.PLAYING:
      if (!G.currentZoneId) enterZone(ZONE_ID.ENTRY);
      if (!G.player) initPlayer(G.currentZoneId);
      break;
    case STATE.PAUSED:
      pauseScreen.cursor = 0;  /* always start on RESUME, not wherever it was left */
      break;
    case STATE.DEAD:
      deadScreen.timer = 0;
      break;
    case STATE.WIN:
      winScreen.timer    = 0;
      winScreen.showText = false;
      break;
  }
}
