      ctx.fillStyle = zpal.platformTop;
      ctx.fillRect(px, py, T16, 2);           /* bright lip */
      ctx.fillStyle = zpal.platformMid;
      ctx.fillRect(px, py + 2, T16, 4);       /* ledge body */
      ctx.fillStyle = zpal.platformBot;
      ctx.fillRect(px, py + 6, T16, 2);       /* underside */
      break;
    }

