        ctx.fillRect(sx,     py + 12, 4, 4);  /* spike base */
        ctx.fillStyle = PAL.FIRE_RED;
        ctx.fillRect(sx + 1, py + 8,  2, 4);  /* spike mid */
        ctx.fillStyle = PAL.LIGHTGRAY;
        ctx.fillRect(sx + 1, py + 6,  2, 2);  /* spike tip */
      }
