```javascript
const canvas = document.getElementById('game');

function updateBouncingBall(s) {
  for (const b of s.balls) {
    b.x += b.vx; b.y += b.vy;
    if (b.x - b.r < 0 || b.x + b.r > canvas.width)  b.vx *= -1;
    if (b.y - b.r < 0 || b.y + b.r > canvas.height) b.vy *= -1;
  }
  s.frameCount++;
  return s;
}
```

```javascript
const ctx = canvas.getContext('2d');

const canvas = document.getElementById('game');

function renderBouncingBall(s) {
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle = '#0a0a0c';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  for (const b of s.balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI*2);
    ctx.fillStyle = b.color + '99';
    ctx.fill();
    ctx.strokeStyle = b.color;
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  // Frame counter
  ctx.fillStyle = '#555566';
  ctx.font = '11px monospace';
  ctx.fillText(`frame ${s.frameCount}`, 12, 20);
  ctx.fillText('update() → render()', 12, canvas.height - 12);
  return s;
}
