        ctx.textAlign='left';
      }
      continue;
    }
    ctx.fillStyle = '#ff5a5a';
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = '#0a0a0c'; ctx.font = 'bold 10px monospace'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('👾', e.x+e.w/2, e.y+e.h/2);
