  const p = s.player;
  ctx.fillStyle = '#7c6bff';
  ctx.beginPath(); ctx.moveTo(p.x+p.w/2, p.y); ctx.lineTo(p.x+p.w, p.y+p.h); ctx.lineTo(p.x, p.y+p.h); ctx.closePath(); ctx.fill();

  // AABB debug label
