  spitter:{ name:'SPITTER', hp:30,  spd:48,  col:'#4a7a30', sz:9,  rv:20, org:'ORG-07', dmg:0,  contactDmg:false, ranged:true },
  charger:{ name:'CHARGER', hp:60,  spd:130, col:'#8a4a20', sz:12, rv:25, org:'ORG-03', dmg:18, contactDmg:true, charger:true },
  crawler:{ name:'CRAWLER', hp:25,  spd:85,  col:'#3a5a2a', sz:7,  rv:15, org:'ORG-04', dmg:6,  contactDmg:true },
  leech:  { name:'LEECH',   hp:45,  spd:72,  col:'#4a1a3a', sz:9,  rv:30, org:'ORG-05', dmg:0,  contactDmg:false, leech:true },
  brute:  { name:'BRUTE',   hp:120, spd:36,  col:'#5a3a6a', sz:16, rv:35, org:'ORG-08', dmg:14, contactDmg:true },
  // ── ELITES (2.5× HP, 1.5× dmg, elite:true flag) ──────────────
  revenant:{ name:'REVENANT', hp:100, spd:60, col:'#8a0a5a', sz:11, rv:35, org:'ORG-06', dmg:18, contactDmg:true, elite:true, teleport:true, teleWait:2, teleT:0 },
  architect:{ name:'ARCHITECT', hp:75, spd:44, col:'#2a5a8a', sz:10, rv:35, org:'ORG-01', dmg:10, contactDmg:false, elite:true, ranged:true, builder:true, buildT:3 },
};

function hitEnemy(idx,dmg){
  if(idx<0||idx>=G.enemies.length) return;
  const e=G.enemies[idx];
  const hasCrit=(G.grafts[0]==='ORG-07'||G.grafts[1]==='ORG-07');
  let d=dmg;
  if(hasCrit&&Math.random()<0.4){
    d*=2;
    boom(e.x,e.y,20,C.bright,{settles:true,spd:200});
    // SYNERGY: crit_gatling — fire two extra projectiles outward on crit
    if(G.synergy==='crit_gatling'){
      const a=Math.atan2(e.y-G.py, e.x-G.px);
      spawnProj(G.px,G.py,e.x+Math.cos(a+0.6)*200,e.y+Math.sin(a+0.6)*200,ORGANS['ORG-01'].dmg,true,C.bright);
      spawnProj(G.px,G.py,e.x+Math.cos(a-0.6)*200,e.y+Math.sin(a-0.6)*200,ORGANS['ORG-01'].dmg,true,C.bright);
    }
  }
  e.hp-=d;
  boom(e.x,e.y,12,C.rouge,{settles:true});
  G.shakeMag=Math.max(G.shakeMag,2);
  if(e.hp<=0) killEnemy(idx);
}
