  // Graft decay — count down in seconds
  for(let i=0;i<2;i++){
    if(!G.grafts[i]) continue;
    G.graftDecay[i]-=dt;
    if(G.graftDecay[i]<=0){
      boom(G.px,G.py,20,C.necro,{spd:160,settles:false});
      G.grafts[i]=''; G.graftDecay[i]=0;
      playSound('decay');
      resolveSynergy();
      updateSynergyHUD();
    }
  }
  return drain;
}
